using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using StockManagement.Data; using StockManagement.Models; using StockManagement.Services;
namespace StockManagement.Controllers;
[Authorize(Roles=Roles.Admin+","+Roles.Manager)] public class AdminController:Controller { private readonly ApplicationDbContext _db; private readonly AuditService _audit; public AdminController(ApplicationDbContext db,AuditService audit){_db=db;_audit=audit;}
public IActionResult Dashboard(){var today=DateTime.UtcNow.Date;return View(new DashboardVm{Products=_db.Products.Count(),Categories=_db.Categories.Count(),Suppliers=_db.Suppliers.Count(),Customers=_db.Customers.Count(),LowStock=_db.Products.Count(x=>x.CurrentStock<=x.ReorderLevel),SalesToday=_db.Sales.Where(x=>x.SaleDate>=today).Sum(x=>(decimal?)x.TotalAmount)??0,PurchasesToday=_db.Purchases.Where(x=>x.PurchaseDate>=today).Sum(x=>(decimal?)x.TotalAmount)??0,LowStockProducts=_db.Products.Include(x=>x.Category).Where(x=>x.CurrentStock<=x.ReorderLevel).OrderBy(x=>x.CurrentStock).Take(8).ToList(),RecentSales=_db.Sales.Include(x=>x.Customer).OrderByDescending(x=>x.SaleDate).Take(8).ToList()});}
public IActionResult Users()=>View(_db.Users.OrderBy(x=>x.FullName).ToList());
[HttpPost,ValidateAntiForgeryToken] public IActionResult ToggleUser(int id){var u=_db.Users.Find(id);if(u!=null){u.IsActive=!u.IsActive;_db.SaveChanges();_audit.Add("User","Update",$"User {u.Email} active={u.IsActive}",User.Identity?.Name??"Admin");}return RedirectToAction(nameof(Users));}
public IActionResult AuditLogs()=>View(_db.AuditLogs.OrderByDescending(x=>x.ChangedAt).Take(200).ToList()); }
